import{_ as r,o as t,c as a,ah as o}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Coach-Tuteur","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/equipe/coach-tuteur.md","filePath":"src/guide/equipe/coach-tuteur.md"}'),n={name:"guide/equipe/coach-tuteur.md"};function s(u,e,i,l,c,d){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="coach-tuteur" tabindex="-1">Coach-Tuteur <a class="header-anchor" href="#coach-tuteur" aria-label="Permalink to &quot;Coach-Tuteur&quot;">​</a></h1><p>Le Coach-Tuteur accompagne individuellement les apprenants d&#39;une cohorte. Son espace de travail est dans <strong>Sève</strong>, avec la messagerie. Dans <strong>Kura</strong>, il retrouve ses cohortes et sa rémunération.</p><h2 id="obtenir-le-role" tabindex="-1">Obtenir le rôle <a class="header-anchor" href="#obtenir-le-role" aria-label="Permalink to &quot;Obtenir le rôle&quot;">​</a></h2><p>Un compte <strong>Canopé</strong> (un ancien apprenant certifié) peut demander le rôle dans <strong>Paramètres → Rôles</strong>. Le Coordinateur pédagogique examine la demande et vous prévient de sa décision. S&#39;il la refuse, il vous donne le motif et vos autres rôles ne changent pas. Le Coordinateur peut aussi vous attribuer le rôle directement.</p><h2 id="vos-cohortes" tabindex="-1">Vos cohortes <a class="header-anchor" href="#vos-cohortes" aria-label="Permalink to &quot;Vos cohortes&quot;">​</a></h2><p>Comme le Formateur, vous ne voyez dans <strong>Formation → Cohortes</strong> que les cohortes auxquelles vous êtes <strong>affecté</strong>. La fiche montre les apprenants, leurs formats et leurs statuts, avec le repère « Pas de droit à l&#39;image » pour ceux qui l&#39;ont refusé, et vous permet de télécharger le <strong>calendrier prévisionnel</strong> de la cohorte.</p><p>Votre nom et votre adresse e-mail figurent dans le <strong>livret d&#39;accueil</strong> des apprenants de la cohorte, pour qu&#39;ils sachent à qui s&#39;adresser.</p><h2 id="encadrer-un-stage" tabindex="-1">Encadrer un stage <a class="header-anchor" href="#encadrer-un-stage" aria-label="Permalink to &quot;Encadrer un stage&quot;">​</a></h2><p>Si la formation comporte un stage, le Coordinateur peut vous désigner <strong>Coach-Tuteur du stage</strong> parmi ceux de la cohorte. Votre nom figure alors sur la <strong>convention de stage</strong>, que l&#39;apprenant et l&#39;entreprise signent. Vous en recevez le PDF une fois la convention contre-signée par edPage group.</p><h2 id="votre-remuneration" tabindex="-1">Votre rémunération <a class="header-anchor" href="#votre-remuneration" aria-label="Permalink to &quot;Votre rémunération&quot;">​</a></h2><p><strong>Finance → Ma rémunération</strong> montre vos lignes cohorte par cohorte, vos versements, et trois totaux : en attente de validation, validé à verser, versé.</p><p>Votre rémunération est un <strong>forfait par apprenant suivi</strong>, calculé par Kura à la fin de la cohorte sur l&#39;effectif présent à son démarrage, même si un apprenant a abandonné ensuite. Les forfaits s&#39;additionnent d&#39;une cohorte à l&#39;autre. Avec plusieurs Coach-Tuteurs sur la même cohorte, elle est partagée à parts égales. Le Coordinateur la valide, puis enregistre le versement fait hors de Kura.</p>',12)])])}const g=r(n,[["render",s]]);export{h as __pageData,g as default};
